        this.addAnnotation((ENamedElement)this.complexDeviceDriverComponentTypeEClass, source, new String[]{"documentation", "The ComplexDeviceDriver Component is a special AtomicSoftwareComponent that has direct access to hardware on an ECUand which is therefore linked to a specific ECU or specific hardware. The ComplexDeviceDriver ComponentType introduces the possibility to link from the software representation to its hardware description provided by the ECU Resource Template.\r\n"});
        this.addAnnotation((ENamedElement)this.getComplexDeviceDriverComponentType_BswModuleDescriptions(), source, new String[]{"documentation", "Reference from the ComplexDeviceDriverComponentType to the Basic Software Module Description describing the BSW part of the Complex Device Driver Component."});
