        this.addAnnotation((ENamedElement)this.ecuAbstractionComponentTypeEClass, source, new String[]{"documentation", "The ECUAbstraction is a special AtomicSoftwareComponent that sits between a component that wants to access ECUperiphery and the Microcontroller Abstraction. The EcuAbstractionComponentType introduces the possibility to link from the software representation to its hardware description provided by the ECU Resource Template."});
