        this.addAnnotation((ENamedElement)this.getEcuAbstractionComponentType_HardwareElements(), source, new String[]{"documentation", "Reference from the EcuAbstractionComponentType to the description of the used HWElements."});
        this.addAnnotation((ENamedElement)this.sensorActuatorSoftwareComponentTypeEClass, source, new String[]{"documentation", "The SensorActuatorSoftwareComponentType introduces the possibility to link from the software representation of a sensor/actuator to its hardware description provided by the ECU Resource Template.\r\n"});
